    public static IServiceCollection AddQualityModule(this IServiceCollection services)
    {
        services.AddSingleton<IModuleManifestProvider, QualityModuleManifestProvider>();
        services.AddSingleton<QualityRepository>();
        services.AddSingleton<Shared.Contracts.Quality.IQualityDecisionCapabilities>(provider => provider.GetRequiredService<QualityRepository>());
        services.AddSingleton<Shared.Contracts.Quality.IQualityReceivingCapabilities>(provider => provider.GetRequiredService<QualityRepository>());
        return services;
    }

