    private static async Task<Access?> AccessAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, Guid? legalEntityId, CancellationToken ct)
    {
        if (!Guid.TryParse(http.User.FindFirstValue("tenant_id"), out var tenantId) || !Guid.TryParse(http.User.FindFirstValue("membership_id"), out var membershipId) || !Guid.TryParse(http.User.FindFirstValue(ClaimTypes.NameIdentifier), out var actorId)) return null;
        var tenant = new TenantId(tenantId); var subject = await subjects.LoadAsync(tenant, membershipId, ct); if (subject is null) return null;
        if (legalEntityId is not null && Guid.TryParse(http.User.FindFirstValue("legal_entity_id"), out var claimEntity) && claimEntity != legalEntityId) return new(tenant, actorId, membershipId, false);
        return new(tenant, actorId, membershipId, authorizer.Authorize(subject, permission, legalEntityId is { } entity ? PermissionScope.ForLegalEntity(tenant, new(entity)) : PermissionScope.ForTenant(tenant)));
    }
    private static async Task<Access?> ResourceAccessAsync(HttpContext http, QualityRepository repo, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, string resourceType, Guid resourceId, CancellationToken ct)
    {
        if (!Guid.TryParse(http.User.FindFirstValue("tenant_id"), out var tenantId)) return null;
        var legalEntityId = await repo.GetLegalEntityForResourceAsync(new TenantId(tenantId), resourceType, resourceId, ct);
        return legalEntityId is null ? new(new TenantId(tenantId), Guid.Empty, Guid.Empty, false) : await AccessAsync(http, subjects, authorizer, permission, legalEntityId, ct);
    }
    private static async Task<IResult> Execute<T>(HttpContext http, Access? access, Func<Task<T>> action, int status = StatusCodes.Status200OK)
    {
        if (access is null) return Results.Unauthorized(); if (!access.Allowed) return Results.Forbid();
        try { var value = await action(); return status == StatusCodes.Status201Created ? Results.Created(http.Request.Path, value) : Results.Ok(value); }
        catch (QualityException ex) { var code = ex.Code.Contains("not_found", StringComparison.Ordinal) ? 404 : ex.Code.Contains("conflict", StringComparison.Ordinal) ? 409 : 400; return Results.Problem(statusCode: code, title: ex.Code, extensions: new Dictionary<string, object?> { ["code"] = ex.Code }); }
    }
    private static TenantId Tenant(HttpContext http) => new(Guid.Parse(http.User.FindFirstValue("tenant_id")!));
    private static Guid Actor(HttpContext http) => Guid.Parse(http.User.FindFirstValue(ClaimTypes.NameIdentifier)!);
    private sealed record Access(TenantId Tenant, Guid ActorId, Guid MembershipId, bool Allowed);
}

